import type { Metadata, Viewport } from "next";
import { site } from "@/content/site";
import { ServiceWorker } from "@/components/shell/service-worker";
import { FRESH_DEMO_PREPAINT } from "@/lib/service/fresh-visit";
// Work Sans (display), Geist and Geist Mono, self-hosted from public/fonts (no font CDN). Generated by scripts/build-fonts.mjs,
// which also keeps the ₮ glyph out of the latin-ext files (see there).
import "./fonts.css";
import "./globals.css";
// Icons: Uicons by Flaticon (flaticon.com/uicons). Subset font + rules generated by `npm run icons`.
import "./uicons.css";

export const metadata: Metadata = {
  metadataBase: new URL(site.url),
  title: { default: site.title, template: `%s · ${site.name}` },
  description: site.description,
  applicationName: site.name,
  alternates: { canonical: "/" },
  appleWebApp: { capable: true, title: site.shortName, statusBarStyle: "default" },
  formatDetection: { telephone: false },
  icons: {
    icon: [{ url: "/icons/icon.svg", type: "image/svg+xml" }],
    apple: [{ url: "/icons/apple-touch-icon.png", sizes: "180x180" }],
  },
  openGraph: { type: "website", siteName: site.name, title: site.title, description: site.description, url: "/", locale: "en_ZA" },
  twitter: { card: "summary_large_image", title: site.title, description: site.description },
  other: { "mobile-web-app-capable": "yes" },
};

export const viewport: Viewport = {
  width: "device-width",
  initialScale: 1,
  viewportFit: "cover",
  // Dark is the default whatever the device prefers, so one colour. PREPAINT and applyTheme() (shell/theme.ts) switch
  // it to white when a saved choice shows the light theme.
  themeColor: site.themeDark,
};

// Demo builds: a first visit (nothing saved, English) is marked <html data-fresh> so the app shows its first screen
// from the server HTML (see lib/service/fresh-visit.ts). Chain builds never mark it.
const FRESH = process.env.NEXT_PUBLIC_DATA_MODE === "chain" ? "" : FRESH_DEMO_PREPAINT;

// Dark needs no script: the bare page is dark (globals.css). This only applies a saved choice (light, dark or system)
// and points theme-color at white when that choice shows light. Keep in step with shell/theme.ts.
const PREPAINT = `try{var d=document.documentElement,l=localStorage,t=l.getItem("heirloom.theme");${FRESH}if(t==="light"||t==="dark"||t==="system"){d.dataset.theme=t;if(t==="light"||(t==="system"&&!matchMedia("(prefers-color-scheme: dark)").matches)){var w=function(){document.querySelectorAll('meta[name="theme-color"]').forEach(function(m){m.content="${site.themeLight}"})};w();document.addEventListener("DOMContentLoaded",w)}}if(l.getItem("heirloom.sidebar")==="collapsed")d.dataset.sidebar="collapsed"}catch(e){}`;

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <html lang="en-ZA" suppressHydrationWarning className="antialiased">
      <head>
        {/* Before first paint: the saved appearance and sidebar width, so a dark choice or a collapsed rail never flashes or shifts the page. */}
        <script dangerouslySetInnerHTML={{ __html: PREPAINT }} />
        {/* The icon subset is tiny (~10 KB) and render-blocking by design (font-display: block), so fetch it early. */}
        <link rel="preload" href="/fonts/uicons-rr-subset.woff2" as="font" type="font/woff2" crossOrigin="anonymous" />
        {/* The latin text faces every page starts with (Mono is only for small addresses, so it isn't preloaded). */}
        <link rel="preload" href="/fonts/work-sans-latin.woff2" as="font" type="font/woff2" crossOrigin="anonymous" />
        <link rel="preload" href="/fonts/geist-latin.woff2" as="font" type="font/woff2" crossOrigin="anonymous" />
      </head>
      <body className="min-h-dvh">
        {children}
        <ServiceWorker />
      </body>
    </html>
  );
}
